artifact.schema:
import type { ReactNode } from 'react';
import type { PatternInstance, PatternId } from './pattern';

// ─── CANONICAL SLOTS (declarative views) ────────────────────────────
export type LayoutSlot =
  | 'header' | 'header.left' | 'header.center' | 'header.right'
  | 'sidebar' | 'sidebar.nav'
  | 'main' | 'main.top' | 'main.bot' | 'main.actions' | 'main.filters' | 'main.tabs'
  | 'right-panel'
  | 'footer'
  | `slot.${string}`;  // namespaced custom slots

// ─── DECLARATIVE VIEW — most common ─────────────────────────────────
export interface LayoutViewSpec {
  readonly id:     string;
  readonly lazy?:  boolean;  // default true
  readonly layout: Partial<Record<LayoutSlot, PatternInstance<any> | PatternInstance<any>[]>>;
  readonly errorBoundary?: { fallback: ReactNode };
}

export function defineLayoutView(spec: LayoutViewSpec): ViewDefinition;

// ─── RENDER VIEW — escape hatch for irregular layouts ───────────────
export interface RenderViewSpec {
  readonly id:       string;
  readonly lazy?:    boolean;
  readonly patterns: PatternInstance<any>[];
  readonly render:   (api: {
    patterns: PatternsResolver;
    slots:    Record<string, ReactNode>;
    ctx:      ResolvedContext;
  }) => ReactNode;
  readonly errorBoundary?: { fallback: ReactNode };
}

export function defineRenderView(spec: RenderViewSpec): ViewDefinition;

// ─── PatternsResolver — type-safe access in custom render ───────────
export interface PatternsResolver {
  render(patternId: PatternId | string): ReactNode;
  has(patternId: PatternId | string): boolean;
}

// ─── ViewDefinition — what both factories return ────────────────────
export interface ViewDefinition {
  readonly id: string;
  readonly kind: 'layout' | 'render';
  readonly lazy: boolean;
  readonly _resolve: (ctx: ResolvedContext) => RenderedView;
}

examples.example:
import { defineLayoutView } from '@surte/core';
import {
  PageHeaderPattern, ProductFiltersPattern,
  ProductTablePattern, PaginationPattern,
} from '@surte/patterns';

export const ProductListView = defineLayoutView({
  id: 'view.products.list',
  lazy: true,
  layout: {
    header:     PageHeaderPattern.instance({ config: { title: 'Productos' } }),
    'main.top': ProductFiltersPattern.instance(),
    'main':     ProductTablePattern.instance({
                  config: { density: 'comfortable', pageSize: 30 },
                  slots:  { rowAction: ProductRowMenu },
                  on:     { rowSelected: ({ productId }) => navigate(`/productos/${productId}`) },
                }),
    'main.bot': PaginationPattern.instance(),
  },
  errorBoundary: { fallback: <ViewErrorFallback id="products.list" /> },
});

import { defineRenderView } from '@surte/core';

export const POSView = defineRenderView({
  id: 'view.sales.pos',
  patterns: [
    ProductSearchPattern.instance(),
    ProductGridPattern.instance({ config: { columns: 4 } }),
    CartPattern.instance(),
    PaymentMethodsPattern.instance({ config: { methods: ['cash', 'yape', 'card'] } }),
    CheckoutButtonPattern.instance(),
  ],
  render: ({ patterns }) => (
    <div className="grid grid-cols-[1fr_400px] h-screen">
      <main className="flex flex-col gap-4 p-6">
        {patterns.render('pattern.product-search')}
        {patterns.render('pattern.product-grid')}
      </main>
      <aside className="border-l">
        {patterns.render('pattern.cart')}
        {patterns.render('pattern.payment-methods')}
        {patterns.render('pattern.checkout-button')}
      </aside>
    </div>
  ),
});
